export const DEFAULT_MEDIA_CACHE_CONTROL = 'private, no-store';
export const MAX_MEDIA_CACHE_CONTROL_LENGTH = 1024;
const PRINTABLE_ASCII_REGEX = /^[\x20-\x7e]+$/;
export const getDownloadResponseHeaderPolicy = ({ logger, responseHeaders })=>{
    const configuredCacheControl = responseHeaders.get('Cache-Control')?.trim();
    const isCacheControlValid = hasValidCacheControl(configuredCacheControl);
    const hasIgnoredHeaders = [
        ...responseHeaders.keys()
    ].some((name)=>name !== 'cache-control');
    const rejectedCacheControlOverride = !isCacheControlValid;
    if (hasIgnoredHeaders || rejectedCacheControlOverride) {
        logger.debug({
            hasIgnoredResponseHeaders: hasIgnoredHeaders,
            msg: 'Filtered media response header overrides',
            rejectedCacheControlOverride
        });
    }
    return {
        cacheControl: isCacheControlValid && configuredCacheControl ? configuredCacheControl : DEFAULT_MEDIA_CACHE_CONTROL
    };
};
function hasValidCacheControl(cacheControl) {
    if (cacheControl == null) {
        return false;
    }
    if (cacheControl.length === 0 || cacheControl.length > MAX_MEDIA_CACHE_CONTROL_LENGTH) {
        return false;
    }
    if (!PRINTABLE_ASCII_REGEX.test(cacheControl)) {
        return false;
    }
    return true;
}
